    if ("none".equalsIgnoreCase(header.algorithm.getName())) {
        throw new MissingVerifierException(
                "Unsigned JWTs are not permitted (algorithm 'none').");
    }

    // Ensure the algorithm is one of the supported, secure algorithms
    if (!SUPPORTED_ALGORITHMS.contains(header.algorithm.getName())) {
        throw new IllegalArgumentException(
                "Unsupported JWT algorithm: " + header.algorithm.getName());
    }

    // If a signature is present, a verifier must be supplied
    if (parts.length == 3 && verifier == null) {
        throw new MissingVerifierException(
                "No Verifier has been provided for verifying a signature signed using ["
                        + header.algorithm.getName() + "]");
    }

    // If a verifier is supplied but no signature exists, treat as invalid
    if (parts.length == 2 && verifier != null) {
        throw new InvalidJWTSignatureException();
    }

    int index = encodedJWT.lastIndexOf(".");
    if (index < 0) {
        throw new IllegalArgumentException("Malformed JWT: missing separator.");
    }

    // The message comprises the first two segments of the entire JWT
    byte[] message = encodedJWT.substring(0, index).getBytes(StandardCharsets.UTF_8);

    if (parts.length == 3) {
        // Verify the signature before deserializing the payload
        byte[] signature = base64Decode(parts[2].getBytes(StandardCharsets.UTF_8));
        verifier.verify(header.algorithm, message, signature);
    }

    JWT jwt = Mapper.deserialize(
            base64Decode(parts[1].getBytes(StandardCharsets.UTF_8)), JWT.class);

    // Verify expiration claim
    if (jwt.isExpired()) {
        throw new JWTExpiredException();
    }

    // Verify the notBefore claim
    if (jwt.isUnavailableForProcessing()) {
        throw new JWTUnavailableForProcessingException();
    }

    return jwt;
