/**
 * Utility class for safely extracting archive entries into a target directory.
 */
public class Expander {

    // other methods

    /**
     * Extracts all readable entries from the supplied archive into {@code targetDirectory}.
     *
     * <p>All entry names are first validated to ensure they do not contain path‑traversal
     * components or absolute paths.  The canonical path of each resulting file is then
     * compared against the canonical path of {@code targetDirectory} to guarantee that
     * extraction never writes outside the intended destination.</p>
     *
     * @param supplier        provides the next readable entry
     * @param writer          writes the entry data to an {@link OutputStream}
     * @param targetDirectory the directory into which entries are extracted
     * @throws IOException if an I/O error occurs or a path traversal attempt is detected
     */
    private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
        // Resolve the canonical path of the target directory once
        Path canonicalTargetDir = targetDirectory.getCanonicalFile().toPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            String entryName = nextEntry.getName();

            // Basic sanitisation: reject absolute paths and any component that resolves to ".."
            if (isInvalidEntryName(entryName)) {
                throw new IOException("invalid entry name: " + entryName);
            }

            // Construct the destination file
            File destFile = new File(targetDirectory, entryName);
            Path canonicalDestPath = destFile.getCanonicalFile().toPath();

            // Ensure the destination stays within the target directory
            if (!canonicalDestPath.startsWith(canonicalTargetDir)) {
                throw new IOException("expanding " + entryName + " would create file outside of " + targetDirectory);
            }

            if (nextEntry.isDirectory()) {
                // Create the directory if it does not already exist
                if (!destFile.isDirectory() && !destFile.mkdirs()) {
                    throw new IOException("failed to create directory " + destFile);
                }
            } else {
                // Ensure parent directories exist
                File parent = destFile.getParentFile();
                if (parent != null) {
                    Path canonicalParentPath = parent.getCanonicalFile().toPath();
                    if (!canonicalParentPath.startsWith(canonicalTargetDir)) {
                        throw new IOException("parent directory of " + entryName + " is outside of " + targetDirectory);
                    }
                    if (!parent.isDirectory() && !parent.mkdirs()) {
                        throw new IOException("failed to create directory " + parent);
                    }
                }

                // Write the file atomically – CREATE_NEW fails if the file already exists
                try (OutputStream out = Files.newOutputStream(destFile.toPath(),
                        StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE)) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    /**
