            return true;
        }

        // Reject any component that resolves to ".."
        // Normalise the path and check for leading ".." components
        Path p = Path.of(name).normalize();
        for (Path part : p) {
            if (part.toString().equals("..")) {
                return true;
            }
        }

        return false;
    }

