/**
 * Implementation of read for STORED entries.
 */
private int readStored(final byte[] buffer, final int offset, final int length) throws IOException {
    // Handle entries that use a data descriptor by delegating to the cached stream.
    if (current.hasDataDescriptor) {
        if (lastStoredEntry == null) {
            readStoredEntry();
        }
        return lastStoredEntry.read(buffer, offset, length);
    }

    // Size of the stored entry must be known; otherwise the ZIP format is invalid.
    final long csize = current.entry.getSize();
    if (csize < 0) {
        throw new IOException("Invalid stored entry size: " + csize);
    }

    // If we've already read the entire entry, signal EOF.
    if (current.bytesRead >= csize) {
        return -1;
    }

    // Determine how many bytes we are allowed to read in this call.
    final long remaining = csize - current.bytesRead;
    final int toRead = (int) Math.min(remaining, length);

    // Refill the internal buffer if it is exhausted.
    if (buf.position() >= buf.limit()) {
        buf.position(0);
        final int l = in.read(buf.array());
        if (l == -1) {
            return -1; // End of underlying stream before expected size.
        }
        if (l == 0) {
            // Avoid an infinite loop if the stream reports 0 bytes read.
            return -1;
        }
        buf.limit(l);
        count(l);
        current.bytesReadFromStream += l;
    }

    // Read from the buffer up to the requested amount or the remaining entry data.
    final int available = buf.remaining();
    if (available == 0) {
        return -1;
    }
    final int readLen = Math.min(toRead, available);
    buf.get(buffer, offset, readLen);
    current.bytesRead += readLen;
    return readLen;
}
