import org.apache.commons.io.IOUtils;
import org.cloudfoundry.identity.uaa.scim.ScimUser;
import org.cloudfoundry.identity.uaa.scim.ScimUserProvisioning;
import org.cloudfoundry.identity.uaa.scim.exception.ScimResourceNotFoundException;
import org.cloudfoundry.identity.uaa.util.JsonUtils;
import org.cloudfoundry.identity.uaa.util.UaaUrlUtils;
import org.cloudfoundry.identity.uaa.zone.IdentityZoneHolder;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.security.Principal;
import java.util.Objects;

public class ScimUserSelfUpdateAllowed {

    private static final Logger LOG = LoggerFactory.getLogger(ScimUserSelfUpdateAllowed.class);

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private ScimUserProvisioning scimUserProvisioning;

    // other methods

    /**
     * Determines whether the current request is allowed to update the SCIM user.
     *
     * <p>The method now enforces that the authenticated user is the owner of the account
     * being updated. It compares the authenticated principal (or username) with the
     * target user ID and username. All field comparisons are performed using
     * {@link Objects#equals(Object, Object)} to avoid NPEs and to allow null values
     * to be handled gracefully.</p>
     *
     * @param request the HTTP request containing the update payload
     * @return {@code true} if the request is allowed, {@code false} otherwise
     * @throws IOException if reading the request body fails
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // Read and parse the request body
        String requestBody = IOUtils.toString(request.getReader());
        ScimUser scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);

        // Extract the target user ID from the URL
        String id = UaaUrlUtils.extractPathVariableFromUrl(USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request));

        // Retrieve the user record from the database
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(id, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist, allow the operation to proceed (e.g., creation)
            return true;
        }

        // Verify that the authenticated user is the owner of the account
        String authenticatedUserId = getAuthenticatedUserId(request);
        if (authenticatedUserId == null) {
            LOG.warn("Unauthenticated request attempted to update user {}", id);
            return false;
        }

        // Allow the request only if the authenticated user matches the target user ID
        // or the target user’s username (fallback for systems where the principal is the username)
        if (!Objects.equals(authenticatedUserId, id) &&
                !Objects.equals(authenticatedUserId, scimUserFromDb.getUserName())) {
            LOG.warn("User '{}' attempted to update account '{}', which it does not own",
                    authenticatedUserId, id);
            return false;
        }

        // Perform field‑by‑field validation using null‑safe comparisons
        if (!Objects.equals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }
        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }
        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        return true;
    }

    /**
     * Retrieves the authenticated user identifier from the request.
     *
     * <p>This method first attempts to obtain the principal name from the request.
     * If the principal is {@code null}, it returns {@code null}. The principal name
     * is expected to be the unique user identifier (e.g., UUID) used by the system.</p>
     *
     * @param request the HTTP request
     * @return the authenticated user ID, or {@code null} if unauthenticated
     */
    private String getAuthenticatedUserId(HttpServletRequest request) {
        Principal principal = request.getUserPrincipal();
        return principal != null ? principal.getName() : null;
    }

    // other methods
}
